import { Rocket } from 'lucide-react';
import { AnimatePresence, motion } from 'motion/react';

export function AnimatedStatusIcon({ type }: { type: 'zap' | 'rocket' }) {
  return (
    <div className="relative flex size-9 shrink-0 items-center justify-center">
      {/* Outer pulsing energy rings (only for zap, representing "charging/setting up") */}
      <AnimatePresence>
        {type === 'zap' ? (
          <>
            <motion.div
              className="absolute inset-0 rounded-full bg-green/20"
              initial={{ scale: 0.8, opacity: 0 }}
              animate={{
                scale: [1, 1.4, 1],
                opacity: [0.5, 0, 0.5],
              }}
              exit={{ opacity: 0, scale: 0.8 }}
              transition={{
                duration: 2,
                repeat: Infinity,
                ease: 'easeInOut',
              }}
            />
            <motion.div
              className="absolute inset-0 rounded-full bg-green/10"
              initial={{ scale: 0.8, opacity: 0 }}
              animate={{
                scale: [1, 1.8, 1],
                opacity: [0.3, 0, 0.3],
              }}
              exit={{ opacity: 0, scale: 0.8 }}
              transition={{
                duration: 2,
                delay: 0.5,
                repeat: Infinity,
                ease: 'easeInOut',
              }}
            />
          </>
        ) : null}
      </AnimatePresence>

      {/* Main icon container */}
      <motion.div
        className="relative flex size-9 items-center justify-center rounded-full border border-green/25 bg-green-bg text-green shadow-[0_0_12px_rgba(30,122,71,0.12)]"
